	damon_for_each_scheme(siter, ctx) {
		if (!siter->walk_completed)
			return;
	}
	damon_for_each_scheme(siter, ctx)
		siter->walk_completed = false;

	complete(&control->completion);
	ctx->walk_control = NULL;
